'use strict';
const $=id=>document.getElementById(id),canvas=$('board'),ctx=canvas.getContext('2d'),P=TinyPhysics,W=540,H=960;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const sprites={};for(const n of ['kiana','blink','joy','yellow','blue']){sprites[n]=new Image();sprites[n].src='assets/'+n+'.png';}
const motion={angle:0,angleV:0,squash:0,squashV:0};
for(const base of ['kiana','yellow','blue'])for(let i=0;i<6;i++){const key=base+'-'+i;sprites[key]=new Image();sprites[key].src='assets/animation/'+key+'.png';}
for(const [base,count] of [['motion',16],['face',12],['yellow',12],['blue',12]])for(let i=0;i<count;i++){const key='new-'+base+'-'+i;sprites[key]=new Image();sprites[key].src='assets/atlas/'+base+'-'+i+'.webp';}
const bubbleArt=new Image();bubbleArt.src='assets/ui/bubble.webp';
let pullDelta=0,dragOrigin=0;
let level=0,bodies=[],targets=[],particles=[],friends=[],hero=null,state='aim',aimX=270,drops=3,usedBounce=false,paused=false,time=0,shotTime=0,settled=0,last=0,acc=0,muted=false,audio=null,dragging=false,completed={},toastTime=0;
try{completed=JSON.parse(localStorage.getItem('tiny-chaos-v1')||'{}');muted=localStorage.getItem('tiny-chaos-muted')==='true';}catch{}
function say(s){$('announcement').textContent=s;}function sound(freq=520,length=.12){if(muted)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!audio)audio=new AC();if(audio.state==='suspended')audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,audio.currentTime+length);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+length);}catch{}}
function hint(s){$('hint').textContent=s;}function sync(){ $('level').textContent='LEVEL '+String(level+1).padStart(2,'0');$('level-name').textContent=LEVELS[level].name;$('drops').innerHTML=Array.from({length:3},(_,i)=>'<i class="'+(i>=drops?'spent':'')+'"></i>').join('');$('drops').setAttribute('aria-label',drops+' drops remaining');const n=targets.filter(t=>t.saved).length;$('rescued').innerHTML=n+' / '+targets.length+' <span class="bubble-icon">●</span>';$('action').disabled=state==='flight'&&usedBounce||state==='won'||state==='lost';$('action').innerHTML=state==='aim'?'DROP <span>↓</span>':usedBounce?'BOUNCE USED':'BOUNCE <span>↑</span>';}
function load(i){level=i;state='aim';pullDelta=0;dragging=false;motion.angle=motion.angleV=motion.squash=motion.squashV=0;drops=3;hero=null;usedBounce=false;aimX=270;particles=[];friends=[];paused=false;bodies=[];targets=LEVELS[i].targets.map((p,j)=>({x:p[0],y:p[1],saved:false,kind:j%2?'blue':'yellow',phase:j*2}));for(const a of LEVELS[i].platforms)bodies.push(P.body(a[0],a[1],a[2],a[3],{a:a[4],static:true,kind:'wood'}));for(const a of LEVELS[i].blocks)bodies.push(P.body(a[0],a[1],a[2],a[3],{mass:.32,kind:'domino',restitution:.18}));for(const a of LEVELS[i].springs)bodies.push(P.body(a[0],a[1],a[2],16,{static:true,kind:'spring',restitution:.9}));if(LEVELS[i].seesaw){const[x,y,w]=LEVELS[i].seesaw;const b=P.body(x,y,w,17,{kind:'seesaw',static:true,pivot:true});b.ii=1/16000;bodies.push(b);}bodies.push(P.body(-5,540,64,650,{static:true,kind:'wall'}),P.body(545,540,64,650,{static:true,kind:'wall'}),P.body(270,828,550,24,{static:true,kind:'floor'}));$('overlay').hidden=true;hint(LEVELS[i].hint);sync();say('Level '+(i+1)+'. '+LEVELS[i].hint);}
function launch(){if(state!=='aim'||paused)return;sound(450,.08);drops--;hero=P.body(aimX,305,54,54,{r:27,mass:1,kind:'hero',activated:true,restitution:.55});hero.vy=15;bodies.push(hero);state='flight';shotTime=0;settled=0;usedBounce=false;hint('Tap once to bounce higher!');sync();}
function burst(x,y,color,count=12){if(reduced)count=4;for(let i=0;i<count;i++){const a=i/count*Math.PI*2;particles.push({x,y,vx:Math.cos(a)*(60+Math.random()*100),vy:Math.sin(a)*(60+Math.random()*100),life:.7,max:.7,color,r:3+Math.random()*4});}}
function bounce(){if(state!=='flight'||usedBounce||paused||!hero)return;usedBounce=true;hero.vy=-550;hero.vx+=hero.x<270?65:-65;hero.squash=-.27;burst(hero.x,hero.y+15,'#ffe8ac',10);sound(750,.2);hint('Beautiful bounce! Let the toys tumble.');sync();}
function act(){if(state==='aim')launch();else bounce();}
function pop(t){t.saved=true;friends.push({x:t.x,y:t.y,kind:t.kind,t:0});burst(t.x,t.y,'#d8fbff',12);sound(620+targets.filter(t=>t.saved).length*120,.2);sync();if(targets.every(t=>t.saved)){state='won';completed[level]=Math.min(completed[level]??4,3-drops);try{localStorage.setItem('tiny-chaos-v1',JSON.stringify(completed));}catch{}toastTime=0;hint('Every friend is free!');sync();say('Level complete. Every friend is free.');}}
function update(dt){time+=dt;const targetAngle=hero?Math.max(-.4,Math.min(.4,hero.vx/650)):dragging?Math.max(-.18,Math.min(.18,pullDelta/900)):Math.sin(time*2)*.035;const targetSquash=hero?(hero.squash||0):dragging?Math.min(.18,Math.abs(pullDelta)/1000):Math.sin(time*3)*.025;motion.angleV+=((targetAngle-motion.angle)*100-motion.angleV*12)*dt;motion.angle+=motion.angleV*dt;motion.squashV+=((targetSquash-motion.squash)*180-motion.squashV*14)*dt;motion.squash+=motion.squashV*dt;for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=240*dt;}particles=particles.filter(p=>p.life>0);for(const f of friends)f.t+=dt;friends=friends.filter(f=>f.t<1.7);if(hero?.squash)hero.squash*=Math.exp(-dt*13);
if(state==='flight'||state==='won'){P.step(bodies,dt,(a,b,s,c)=>{if(a.activated||b.activated){if(a.im)a.activated=true;if(b.im)b.activated=true;}if(a.kind==='hero'||b.kind==='hero'){hero.squash=Math.min(.25,s/1800);if(s>150)sound(170,.06);}const spring=a.kind==='spring'?a:b.kind==='spring'?b:null,other=spring===a?b:a;if(spring&&other.im&&other.y<spring.y){other.vy=-650;spring.press=.2;burst(other.x,other.y,'#caf2ce',6);}});for(const b of bodies){b.av=Math.max(-8,Math.min(8,b.av));if(b.press)b.press*=.93;}
if(state==='flight'){shotTime+=dt;for(const t of targets){if(t.saved)continue;for(const b of bodies){if(!b.im)continue;if(P.hit(b,{x:t.x,y:t.y,r:33})&&(b.kind==='hero'||b.activated&&Math.hypot(b.vx,b.vy)>40)){pop(t);break;}}}if(state==='flight'){if(hero.y>870||shotTime>7||(shotTime>1.2&&Math.hypot(hero.vx,hero.vy)<22)){settled+=dt;}else settled=0;if(settled>.7||shotTime>8){bodies=bodies.filter(b=>b!==hero);hero=null;if(drops>0){state='aim';hint('Try a new drop position. Your rescues stay!');}else{state='lost';hint('So close! Try a different route.');showResult(false);}sync();}}}
if(state==='won'){toastTime+=dt;if(toastTime>1.4&&$('overlay').hidden)showResult(true);}}
}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function sprite(name,x,y,size,sx=1,sy=1,rot=0){const fallback=name.includes('yellow')?sprites.yellow:name.includes('blue')?sprites.blue:sprites.kiana;const im=sprites[name]?.naturalWidth?sprites[name]:fallback;ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.scale(sx,sy);if(im.complete&&im.naturalWidth){const ratio=im.naturalHeight/im.naturalWidth;ctx.drawImage(im,-size/2,-size*ratio/2,size,size*ratio);}else{ctx.fillStyle=name==='kiana'?'#fc9c80':name==='blue'?'#a6c3f0':'#ffdf8a';ctx.beginPath();ctx.arc(0,0,size*.4,0,7);ctx.fill();}ctx.restore();}
function pulledKiana(x,y,delta){const amount=Math.min(1,Math.abs(delta)/145),dir=Math.sign(delta)||1;const stretch=1+amount*.58,squash=1-amount*.2;ctx.save();if(amount>.08&&!reduced){ctx.globalAlpha=.12+.08*amount;ctx.fillStyle='#ff9d83';for(let i=3;i>0;i--){const trailX=x-dir*(20+i*10)*amount;ctx.beginPath();ctx.ellipse(trailX,y+4,18+i*5,24-i*2,0,0,7);ctx.fill();}ctx.globalAlpha=1;}ctx.restore();sprite(amount>.25?'new-face-4':'new-face-0',x-dir*7*amount,y,96,stretch,squash,dir*amount*.075);}
function wood(b){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.a);ctx.shadowColor='#563f302b';ctx.shadowBlur=10;ctx.shadowOffsetY=7;let fill=ctx.createLinearGradient(0,-b.h/2,0,b.h/2);const coral=b.kind==='domino',yellow=b.kind==='seesaw';fill.addColorStop(0,coral?'#ffb29a':yellow?'#ffe5a1':'#f7d5a2');fill.addColorStop(1,coral?'#e77863':yellow?'#ddb15c':'#bd8754');rr(-b.w/2,-b.h/2,b.w,b.h,Math.min(6,b.w/4),fill,'#98644055');ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle=coral?'#fff3dc55':'#a7784740';ctx.lineWidth=1;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-b.w/2+7,-b.h/2+5+i*4);ctx.bezierCurveTo(-b.w*.1,-b.h/2+8+i*4,b.w*.2,-b.h/2+2+i*4,b.w/2-7,-b.h/2+5+i*4);ctx.stroke();}if(coral){ctx.fillStyle='#fff2cf';ctx.beginPath();ctx.arc(0,-b.h*.23,3,0,7);ctx.fill();}else{ctx.fillStyle='#a87545';for(const x of [-b.w/2+12,b.w/2-12]){ctx.beginPath();ctx.arc(x,0,2.8,0,7);ctx.fill();}}ctx.restore();}
function bubble(t){if(t.saved)return;const y=t.y+(reduced?0:Math.sin(time*2+t.phase)*3);const blink=!reduced&&Math.sin(time*.9+t.phase)>.99;const alert=hero&&Math.hypot(hero.x-t.x,hero.y-t.y)<140;sprite('new-'+t.kind+'-'+(alert?7:blink?3:Math.sin(time*3+t.phase)>.6?1:0),t.x,y,55,1+Math.sin(time*3+t.phase)*.025,1-Math.sin(time*3+t.phase)*.025);if(bubbleArt.complete&&bubbleArt.naturalWidth){ctx.drawImage(bubbleArt,t.x-43,y-43,86,86);return;}ctx.save();const g=ctx.createRadialGradient(t.x-12,y-15,2,t.x,y,37);g.addColorStop(0,'#ffffff06');g.addColorStop(.7,'#d4eaff16');g.addColorStop(.93,'#a9d7e58a');g.addColorStop(1,'#fffbeed9');ctx.fillStyle=g;ctx.beginPath();ctx.arc(t.x,y,37,0,7);ctx.fill();ctx.strokeStyle='#fff9f2d9';ctx.lineWidth=2;ctx.stroke();ctx.strokeStyle='#fffdf5';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.arc(t.x,y,29,3.75,4.55);ctx.stroke();ctx.restore();}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);const ww=Math.round(rect.width*dpr),hh=Math.round(rect.height*dpr);if(canvas.width!==ww||canvas.height!==hh){canvas.width=ww;canvas.height=hh;}ctx.setTransform(ww/W,0,0,hh/H,0,0);ctx.clearRect(0,0,W,H);
// Soft catch cushion anchors the playfield.
ctx.fillStyle='#456b5840';ctx.beginPath();ctx.ellipse(270,838,195,17,0,0,7);ctx.fill();rr(55,802,430,39,22,'#85b9a5','#4e8c81');rr(70,799,400,22,13,'#fff0d4','#e3d4af');
for(const b of bodies){if(['wall','floor','hero'].includes(b.kind))continue;if(b.kind==='seesaw'){ctx.fillStyle='#75a899';ctx.beginPath();ctx.moveTo(b.x,b.y+7);ctx.lineTo(b.x-24,b.y+55);ctx.lineTo(b.x+24,b.y+55);ctx.closePath();ctx.fill();}if(b.kind==='spring'){ctx.save();ctx.translate(b.x,b.y);ctx.strokeStyle='#687a6b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-15,24);for(let k=0;k<6;k++)ctx.lineTo(k%2?15:-15,24-k*4);ctx.stroke();rr(-b.w/2,-10,b.w,18,9,'#9dcdb1','#57988a');ctx.restore();}else wood(b);}
for(const t of targets)bubble(t);for(const f of friends){const scale=1+Math.sin(f.t*9)*.08; sprite('new-'+f.kind+'-'+(f.t<.25?9:f.t<.7?10:11),f.x+Math.sin(f.t*4)*18,f.y-f.t*70,50,scale,1/scale,Math.sin(f.t*8)*.12);}
if(state==='aim'){ctx.save();ctx.strokeStyle='#fff8e8cc';ctx.setLineDash([3,11]);ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(aimX,350);ctx.lineTo(aimX,390);ctx.stroke();ctx.restore();const blink=Math.sin(time*.8)>.994,y=305+(reduced?0:Math.sin(time*2.5)*4);if(dragging)pulledKiana(aimX,y,pullDelta);else sprite('new-face-'+(blink?2:0),aimX,y,96,1+motion.squash,1-motion.squash,motion.angle);}
if(hero){const stretch=motion.squash,fall=Math.min(.12,Math.abs(hero.vy)/5000),rot=Math.max(-.4,Math.min(.4,hero.vx/650));if(!reduced&&state==='flight'&&Math.abs(hero.vy)>150){ctx.globalAlpha=.14;sprite('new-face-0',hero.x-hero.vx*.025,hero.y-hero.vy*.025,73);ctx.globalAlpha=1;}const pose=state==='won'?'new-face-11':(hero.squash||0)>.15?'new-face-8':shotTime<.14?'new-face-3':'new-face-0';const speedStretch=Math.min(.28,Math.abs(hero.vy)/2200);sprite(pose,hero.x,hero.y-4,92,1+stretch-fall-speedStretch*.35,1-stretch+fall+speedStretch,motion.angle);}
for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();}ctx.globalAlpha=1;
}
function overlay(html){dragging=false;paused=true;$('overlay').hidden=false;$('panel').innerHTML=html;decorateUI();const first=$('panel').querySelector('button');if(first)first.focus();}
function showResult(win){overlay('<div class="eyebrow">'+(win?'LITTLE CHAOS, BIG SMILES':'A NEW ROUTE AWAITS')+'</div><img alt="Happy Kiana" src="assets/atlas/face-'+(win?'11':'10')+'.webp"><h1>'+(win?'Friends, freed!':'One more try?')+'</h1><p>'+(win?'You rescued every little friend.<br>'+ (3-drops)+' drop'+(3-drops===1?'':'s')+'. Beautifully done.':'The bubbles you missed are waiting.<br>Change your drop position or bounce timing.')+'</p><button class="primary" id="result-main">'+(win?(level===LEVELS.length-1?'See your adventure':'Next little adventure'):'Try this level again')+'</button><button class="secondary" id="result-levels">Choose a level</button>');$('result-main').onclick=()=>{if(win&&level===LEVELS.length-1)levelMenu();else load(win?level+1:level);};$('result-levels').onclick=levelMenu;}
function levelMenu(){overlay('<div class="eyebrow">BEDROOM ADVENTURES</div><h1>Little adventures</h1><p>Ten puzzles. Find your own way.<br>Completed levels are marked in green.</p><div class="level-grid">'+LEVELS.map((l,i)=>'<button class="'+(completed[i]?'complete':'')+'" data-level="'+i+'" aria-label="Level '+(i+1)+': '+l.name+(completed[i]?', completed':'')+'">'+(i+1)+(completed[i]?'<small>'+('★'.repeat(4-completed[i]))+'</small>':'')+'</button>').join('')+'</div><button class="secondary" id="back">Back to game</button><p style="font-size:10px">Playable prototype · progress stays on this device.</p>');for(const b of $('panel').querySelectorAll('[data-level]'))b.onclick=()=>load(Number(b.dataset.level));$('back').onclick=resume;}
function resume(){paused=false;$('overlay').hidden=true;last=performance.now();acc=0;canvas.focus();}
$('pause').onclick=()=>{if(paused)return;overlay('<div class="eyebrow">TAKE YOUR TIME</div><h1>A little pause</h1><p>Your puzzle will be right here.</p><button class="primary" id="resume">Keep playing</button><button class="secondary" id="pick">Choose a level</button>');$('resume').onclick=resume;$('pick').onclick=levelMenu;};$('retry').onclick=()=>load(level);$('level').onclick=levelMenu;$('title').onclick=homeMenu;$('action').onclick=act;$('help').onclick=()=>{overlay('<div class="eyebrow">ONE DROP. ONE BOUNCE.</div><h1>Make a little chaos.</h1><p><strong>1. Slide and release</strong><br>Choose where Kiana drops. Or use the Drop button.<br><strong>2. Tap for a bounce</strong><br>One upward boost per drop. Time it well!<br><strong>3. Free every friend</strong><br>Kiana and moving toys can pop bubbles.<br>You have three drops. Retry whenever you like.</p><button class="primary" id="got-it">Let’s play</button>');$('got-it').onclick=resume;};
function syncSound(){$('sound').dataset.muted=String(muted);$('sound').textContent=muted?'Sound off':'Sound on';$('sound').setAttribute('aria-label',muted?'Turn sound on':'Mute sound');}syncSound();$('sound').onclick=()=>{muted=!muted;syncSound();try{localStorage.setItem('tiny-chaos-muted',String(muted));}catch{}if(!muted)sound();};
function pointerX(e){const r=canvas.getBoundingClientRect();return Math.max(65,Math.min(475,(e.clientX-r.left)/r.width*W));}
canvas.addEventListener('pointerdown',e=>{if(paused)return;canvas.focus();if(state==='aim'){dragging=true;dragOrigin=pointerX(e);pullDelta=0;aimX=pointerX(e);canvas.setPointerCapture(e.pointerId);hint('Release to drop Kiana.');}else if(state==='flight')bounce();});canvas.addEventListener('pointermove',e=>{if(dragging&&state==='aim'){aimX=pointerX(e);pullDelta=aimX-dragOrigin;}});canvas.addEventListener('pointerup',()=>{if(dragging){dragging=false;launch();}});canvas.addEventListener('pointercancel',()=>{dragging=false;hint('Slide to aim. Release to drop.');});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();if(paused)return;if(e.key==='ArrowLeft')aimX=Math.max(65,aimX-15);if(e.key==='ArrowRight')aimX=Math.min(475,aimX+15);if(e.key===' '||e.key==='Enter')act();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('overlay').hidden)resume();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused)$('pause').click();});
function frame(now){const menuHero=$('panel').querySelector('.menu-hero');if(menuHero){const f=[0,0,0,1,2,0,5,6,7,4][Math.floor(now/450)%10];const path='assets/atlas/face-'+f+'.webp';if(menuHero.getAttribute('src')!==path)menuHero.src=path;}if(!last)last=now;const dt=Math.min((now-last)/1000,.05);last=now;if(!paused){acc+=dt;while(acc>=1/120){update(1/120);acc-=1/120;}}draw();requestAnimationFrame(frame);}load(0);homeMenu();requestAnimationFrame(frame);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
// Keep keyboard focus inside an open in-game panel.
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('overlay').hidden)return;const buttons=Array.from($('panel').querySelectorAll('button:not(:disabled)'));if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});

function homeMenu(){const total=Object.values(completed).reduce((a,n)=>a+4-n,0);overlay('<div class="eyebrow">A LITTLE WORLD OF BIG REACTIONS</div><h1 class="home-logo">KIANA<span>TINY CHAOS</span></h1><img class="menu-hero" alt="Kiana" src="assets/atlas/face-0.webp"><p>Drop. Bounce. Free your little friends.</p><button class="primary" id="journey">PLAY</button><button class="secondary" id="adventures">LEVELS · '+Object.keys(completed).length+' / '+LEVELS.length+'</button><button class="secondary" id="album">MEET YOUR FRIENDS</button><p class="menu-stars">★ '+total+' / '+LEVELS.length*3+'</p><p style="font-size:10px">Progress saved on this device · playtest build</p>');$('journey').onclick=()=>load(LEVELS.findIndex((_,i)=>!completed[i])<0?0:LEVELS.findIndex((_,i)=>!completed[i]));$('adventures').onclick=levelMenu;$('album').onclick=albumMenu;}
function albumMenu(){overlay('<div class="eyebrow">LITTLE FRIENDS, BIG PERSONALITIES</div><h1>The cuddle crew</h1><div class="album">'+[['kiana','Kiana','The brave little bouncer'],['yellow','Sunny','A happy little sprout'],['blue','Pip','A curious cloud of joy']].map(([id,name,desc])=>'<div><img alt="'+name+'" src="assets/atlas/'+(id==='kiana'?'face-11':id+'-11')+'.webp"><strong>'+name+'</strong><small>'+desc+'</small></div>').join('')+'</div><button class="primary" id="album-back">BACK HOME</button>');$('album-back').onclick=homeMenu;}

function decorateUI(){const close=document.createElement('button');close.className='panel-close';close.setAttribute('aria-label','Close menu');close.onclick=resume;$('panel').append(close);const stars=$('panel').querySelector('.menu-stars');if(stars){stars.textContent=stars.textContent.replace('★','').trim();const im=document.createElement('img');im.src='assets/ui/star.webp';im.className='reward-star';im.alt='Stars';stars.prepend(im);}const heroImage=$('panel').querySelector('.menu-hero');if(heroImage)heroImage.dataset.animated='true';}
